import { useState, useEffect } from "react";
import {
  listarEvaluacionesPsico,
  eliminarEvaluacionPsico,
} from "../../servicios/evaluacionPsico";
import EvaluacionPsicoForm from "./EvaluacionPsicoForm";

function EvaluacionPsicolist() {
  const [evaluaciones, setEvaluaciones] = useState([]);
  const [loading, setLoading] = useState(true);
  const [selectedEval, setSelectedEval] = useState(null);

  const cargarEvaluaciones = async () => {
    setLoading(true);
    try {
      const data = await listarEvaluacionesPsico();
      setEvaluaciones(data);
    } catch (err) {
      console.error(err);
      alert("❌ Error al cargar evaluaciones psicopedagógicas");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    cargarEvaluaciones();
  }, []);

  const handleDelete = async (id) => {
    if (!window.confirm("¿Eliminar esta evaluación?")) return;

    try {
      await eliminarEvaluacionPsico(id);
      cargarEvaluaciones();
    } catch (err) {
      console.error(err);
      alert("❌ Error al eliminar la evaluación");
    }
  };

  const handleSuccess = () => {
    setSelectedEval(null);
    cargarEvaluaciones();
  };

  return (
    <div style={{ display: "flex", gap: "2rem" }}>
      {/* LISTADO */}
      <div style={{ flex: 1 }}>
        <h2>Evaluaciones Psicopedagógicas</h2>

        {loading ? (
          <p>Cargando...</p>
        ) : (
          <table border="1" cellPadding="5" width="100%">
            <thead>
              <tr>
                <th>ID</th>
                <th>Evaluación Integral</th>
                <th>Fecha</th>
                <th>Evaluador</th>
                <th>Acción</th>
              </tr>
            </thead>

            <tbody>
              {evaluaciones.map((ev) => (
                <tr key={ev.id}>
                  <td>{ev.id}</td>
                  <td>{ev.evaluacion_integral}</td>
                  <td>{ev.fecha || "-"}</td>
                  <td>{ev.evaluador || "-"}</td>
                  <td>
                    <button onClick={() => setSelectedEval(ev)}>Editar</button>
                    <button
                      onClick={() => handleDelete(ev.id)}
                      style={{ marginLeft: "5px" }}
                    >
                      Eliminar
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>

      {/* FORMULARIO */}
      <div style={{ flex: 1 }}>
        <h2>{selectedEval ? "Editar evaluación" : "Nueva evaluación"}</h2>

        <EvaluacionPsicoForm evaluacion={selectedEval} onSuccess={handleSuccess} />
      </div>
    </div>
  );
}

export default EvaluacionPsicolist;
